//! ♻️ The real PNG inflater adapter forwards independent close work and leaves fixed-header copies zero.
use super::*;
use semio_framework_value::retirement::{RetirementCursor,RetirementStep};
#[global_allocator]
static ALLOCATOR:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn observed<T>(step:impl FnOnce()->T)->(T,(usize,usize)){let(output,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(step);assert!(!heap.overflowed,"physical test allocator observation overflow");(output,(heap.requested_bytes,heap.released_bytes))}
#[test]fn png_inflater_retirement_keeps_denied_custody_and_counts_each_actual_effect(){let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../🗜️deflate/🚰️inflater/♻️close/📐️.json")).unwrap();let n=law["allocationBytes"].as_u64().unwrap()as usize;let mut inflater=Inflater::try_new_retained(law["historyBytes"].as_u64().unwrap()as usize,n).unwrap();let(result,heap)=observed(||inflater.reserve_retained_history(n));assert_eq!(result.unwrap().allocated_bytes,n);assert_eq!(heap,(n,0));let pointer=inflater.retained_history_ptr();let mut owner=PngInflaterRetirement{owner:Some(PngInflater(inflater))};let schedule=[(0,0),(1,0),(1,0),(1,n-1),(1,n),(1,0),(0,0)];let mut remaining_items=law["adapterItems"].as_u64().unwrap()as usize;let mut remaining_release=n;for(index,(items,release))in schedule.into_iter().enumerate(){let grant=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:release,maximum_depth:1};assert!(items<=remaining_items&&release<=remaining_release);assert_eq!(owner.next_demand(0).unwrap().copy_bytes,law["headerCopyBytes"].as_u64().unwrap()as usize);let(step,heap)=observed(||owner.close_step(grant));assert_eq!(step.work(),law["adapterCpu"][index].as_u64().unwrap());let p=match step{RetirementStep::Progress(progress,_)=>progress,RetirementStep::BudgetExhausted|RetirementStep::Complete(_)=>Default::default(),_=>panic!("unexpected inflater close outcome")};assert!(p.fits(grant));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(p.copied_bytes,0);remaining_items-=p.copied_items;remaining_release-=p.released_bytes;if index<4{assert_eq!(owner.owner.as_ref().unwrap().retained_history_ptr(),pointer);}if index==4{assert!(owner.owner.is_some());assert!(owner.owner.as_ref().unwrap().retained_terminal_is_empty());assert!(!owner.terminal_is_empty());}}assert_eq!((remaining_items,remaining_release),(0,0));assert!(owner.terminal_is_empty());let((),heap)=observed(||drop(owner));assert_eq!(heap,(0,0));}
